const evidence=require('../assets/comparison-evidence-20261030.json');
const {courses,jobs}=evidence;
const table=(caption,heads,rows)=>`<div class="verified-table" tabindex="0" role="region" aria-label="${caption}"><table><caption>${caption}</caption><thead><tr>${heads.map(h=>'<th scope="col">'+h+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
const link=(href,text)=>`<a href="${href.replaceAll('&','&amp;')}" target="_blank" rel="noopener noreferrer">${text}</a>`;
const job=id=>jobs.find(j=>j.id===id);
const jobRows=ids=>ids.map(id=>{const j=job(id);return [link(j.url,j.name),j.experience+' / '+j.qualification,j.schedule,j.issue+' · '+j.status]});
const center=`<section data-value-repair="20261030"><h2>지역 센터를 찾고 예약하는 순서</h2><p>센터 위치 확인과 이용 준비를 한 안내로 합쳤습니다. 먼저 고용24의 <a href="https://m.work24.go.kr/wk/u/a/1000/seniorCenterInfo.do" target="_blank" rel="noopener noreferrer">중장년내일센터 공식 현황</a>에서 기관명·주소·연락처를 찾습니다. 중장년내일센터, 고용복지플러스센터의 전담 창구, 지자체 일자리센터는 이름과 담당 서비스가 다를 수 있습니다. 지도에서 가까운 건물만 고르기보다 원하는 상담을 제공하는지 전화로 확인하세요.</p><ol><li>현재 상태를 재직·퇴직예정·구직 중으로 구분합니다.</li><li>공식 현황에서 생활권 기관을 찾고 실제 방문 장소를 확인합니다.</li><li>상담 목적, 예약 방식, 대상 조건, 준비물을 문의합니다.</li><li>접수와 일정 확정 안내를 확인한 뒤 방문합니다.</li></ol><h2>전화할 때 말할 내용을 완성하는 예</h2><p>다음은 실제 상담 후기가 아닌 작성 예입니다. “올해 퇴직했고 물류 입출고 업무를 했습니다. 시설관리로 전환할지 고민 중인데 경력 상담을 예약할 수 있을까요? 야간은 어렵고 통근은 편도 1시간까지 가능합니다. 첫 방문에 이력서가 필요한가요?”처럼 현재 경력·희망 직무·제약·질문을 나누면 상담 목적이 명확해집니다.</p><p>이 문장을 그대로 외우기보다 자신의 사실로 바꾸세요. 전화 예약만으로 온라인 서비스 신청이 끝나거나 수당이 신청되는 것은 아닙니다. 제도 신청이 목적이면 해당 기관의 담당 여부와 별도 창구를 물어보세요. 무료 상담이나 알선은 채용 확정을 의미하지 않습니다.</p></section>`;
const general=`<section data-value-repair="20261030"><h2>자격증 후보보다 바꿀 수 없는 조건을 먼저 적으세요</h2><p>재취업 자격증 선택은 인기 순위를 찾는 일이 아니라 지원할 일과 교육을 연결하는 일입니다. 오늘 바로 바꾸기 어려운 통근수단·근무시간·가족 돌봄 조건을 먼저 적습니다. 그다음 경력·자격·교육으로 보완 가능한 항목을 나누세요. 필수조건이 맞지 않는 공고를 자격증 하나로 해결할 수 있다고 생각하면 준비비를 잘못 쓰게 됩니다.</p><p>아래 공고는 2026년 10월 30일 열람한 과거·공개 표본이며 현재 모집목록이나 전국 평균이 아닙니다. 전기 분야의 임금 비교는 별도 전기 취업 글에 두고, 이 글에서는 서로 다른 직무의 진입 조건을 거르는 방법에 집중합니다.</p><h2>자격·경력·시간이 각각 다른 조건인 세 사례</h2>${table('직무를 고르기 위한 공고 표본',['공고 원문','경력·자격 표기','근무표','먼저 확인할 점'],jobRows(['J05','J08','J10']))}<h2>완성된 선택 메모의 가상 예</h2><p>예를 들어 운전하지 않고 야간근무가 어려운 구직자라면, 자차 필수 조리원 공고는 신입 가능이라는 문구만으로 선택할 수 없습니다. 지게차 2교대 표본은 최소 1년 경력이 필수라서 자격 취득만으로 그 요건을 채우지 못합니다. 요양원 표본은 주간·교대 표기가 섞여 있어 실제 배정을 확인하기 전까지 판단 보류로 남깁니다. 이것은 세 직무의 우열이 아니라 이 가상 구직자의 조건을 적용한 결과입니다.</p>${table('내 조건으로 거르는 작성 예',['항목','가상 입력','분류와 다음 행동'],[['통근','대중교통만 사용, 편도 60분 이내','자차 필수 공고는 현재 조건 부적합'],['근무시간','야간 불가','야간 포함 공고와 배정 미확인 공고를 구분'],['경력','해당 장비 경력 없음','경력 필수와 우대를 구분'],['교육','주말에 학습 가능','직무 후보가 남은 뒤 훈련시간표 대조']])}<h2>후보가 남으면 자격과 훈련을 연결합니다</h2><p>생활권의 실제 공고 세 건에서 같은 자격이 필수인지 우대인지 나누고, 직접 맡을 업무를 적으세요. 자격 우대 공고가 있다고 모든 전기 업무·법정 선임이 가능한 것은 아닙니다. 돌봄 업무 역시 자격 취득 외 실제 계약·교대표·이동 조건을 확인해야 합니다. 조건이 비어 있으면 가능 또는 불가로 추정하지 말고 채용처에 물을 질문으로 남깁니다.</p><p>훈련을 비교할 때는 같은 자격명보다 수업 방식, 개인 실습 기회, 본인 부담금과 통학비를 봅니다. 메인의 계산기는 입력한 비용을 더하는 도구이지 지원 자격 판정이나 학원 추천 순위가 아닙니다. 필수조건이 확인되지 않았다면 결제보다 상담이 먼저이며, 합격 수업과 취업 알선 범위도 구분해 물어보세요.</p><h2>오늘 남길 결과는 추천 목록이 아니라 지원 계획입니다</h2><p>첫째, 원문 주소·확인일·근무표·자격·경력 칸이 있는 비교표를 만듭니다. 둘째, 미확인 항목을 담당자에게 물어 답변 날짜와 함께 적습니다. 셋째, 지원 가능한 일에 부족한 교육 하나를 정합니다. 결과적으로 자격증 취득을 미루거나 다른 직무를 고르는 결론도 가능합니다. 특정 자격을 무조건 취득하는 것이 이 안내의 목적은 아닙니다.</p><h2>자주 묻는 질문</h2><h3>신입 모집이면 자격증이 필요 없나요?</h3><p>신입 여부와 자격 필수·우대는 별도입니다. 담당업무와 근무조건도 함께 봐야 합니다.</p><h3>비어 있는 경력 칸은 경력무관인가요?</h3><p>미표기를 경력무관으로 바꾸지 마세요. 담당자에게 확인할 항목입니다.</p><h3>내 조건에 맞는 공고가 없으면 무엇을 하나요?</h3><p>통근 범위나 희망 직무를 다시 비교하고 경력 상담을 받을 수 있습니다. 원하는 공고가 없는 상태에서 자격증 개수부터 늘리지 마세요.</p></section>`;
const electric=`<section data-value-repair="20261030"><h2>시설관리와 설치직을 자격증 이름만으로 묶지 않습니다</h2><p>전기기능사 50대 취업을 검토할 때는 설치·통신 작업, 건물의 시설 보수, 경력 현장책임자를 먼저 구분합니다. 아래 자료는 2026년 10월 30일 열람한 공고 표본이지 연령별 채용 실적이 아닙니다. 신입 공고의 존재만으로 50대의 합격 가능성을 계산하지 않습니다.</p>${table('서로 다른 직무의 공개 표본',['공고 원문','경력·자격 표기','근무표','직무별 확인사항'],jobRows(['J03','J01','J02','J04']))}<h2>월급이 아니라 첫 달의 일을 비교하는 질문</h2><p>설치 신입 표본은 전기기능사·방송통신기능사 우대와 케이블·CCTV 설치 업무가 함께 있습니다. 관심이 있다면 첫 달에 맡을 작업, 현장 이동 범위, 운전 필요, 함께 일할 인원, 안전교육과 지시 체계를 물어보세요. 이 항목은 확인 질문이며 해당 기업이 모두 필수라고 공고했다는 뜻은 아닙니다.</p><p>시설관리 두 표본은 전기 자격이 필수라는 표기를 제공 본문에서 확인하지 못했습니다. 따라서 이 사례를 전기기능사가 있으면 바로 채용되는 증거로 쓰지 않습니다. 영선·보수 범위, 전기 외 작업, 인수인계와 별도 선임요건을 확인해야 합니다. 자격명은 같아도 실제 맡는 일과 법정 역할은 다를 수 있습니다.</p><h2>근무표를 계산하면 추가 질문이 보입니다</h2><p>기숙사 표본은 10~20시 중 휴게 2시간으로 표시된 구간과 일요일 16~22시 안내가 별도로 있습니다. 앞 구간만 단순 계산하면 체류 10시간에서 휴게 2시간을 뺀 8시간이지만, 이것만으로 전체 주간 근로시간과 수당을 확정할 수는 없습니다. 일요일 배정, 근무일 순환, 급식비·휴일수당 포함 범위를 실제 근무표와 계약서에서 대조해야 합니다.</p><p>월 450만원 이상 현장책임자 표본은 최소 10년 경력 필수입니다. 자격 없어도 지원 가능이라는 본문이 있더라도 경력요건까지 사라지지 않습니다. 초보자가 자격 취득 직후 받을 월급으로 읽으면 안 됩니다. 구조화 항목의 주6일과 본문의 토요일 격주휴무처럼 다른 표기가 있으면 채용처 답변 전까지 미확인으로 남깁니다.</p><h2>지원서에는 시험 경험과 현장 경력을 나눕니다</h2><p>가상의 기입 예로 “전기기능사 취득, 교육장 배관·배선 과제 실습”은 실제 이수 사실에 맞춰 쓸 수 있지만 “건물 전기 유지보수 경력”으로 바꾸면 안 됩니다. 신입은 배운 작업과 지도받을 부분을 구분하고, 경력자는 담당 설비·고장 대응·점검 기록 중 확인 가능한 경험을 정리하세요. 타인의 성과나 전 회사 비공개 자료를 가져오지 않습니다.</p><p>교육 상담에서도 시험 합격용 실습과 취업 연계 직무를 별도로 묻습니다. 현장 실습이 있다고 할 때 본인이 한 작업, 감독 방식, 안전교육, 소개 공고의 경력 조건을 확인하세요. 자격 취득 자체로 모든 설비의 법정 선임이나 독립 작업 권한이 생긴다고 해석하지 않습니다.</p><h2>자주 묻는 질문</h2><h3>시설관리 공고면 전기기능사가 필수인가요?</h3><p>표본만으로 그렇게 말할 수 없습니다. 담당업무와 자격·선임조건을 정확히 읽어야 합니다.</p><h3>신입 설치직과 시설관리 중 무엇이 낫나요?</h3><p>현장 이동, 실제 업무, 근무표와 교육 조건이 다릅니다. 통근과 야간 가능 여부 등 본인의 조건으로 비교하세요.</p><h3>신입 공고가 있으면 50대 채용도 확정인가요?</h3><p>아닙니다. 연령별 실적을 조사한 자료가 아니며 실제 지원 가능 여부와 선발은 채용처에 확인해야 합니다.</p></section>`;
const forest=`<section class="fact-followup" data-fact-review="20261030" data-value-repair="20261030"><h2>산림과 조경의 시험료를 따로 계산합니다</h2>${table('2026년 10월 30일 Q-Net에서 확인한 시험료',['종목','필기 1회','실기 1회','각 1회 합계'],[['산림기능사','14,500원','64,200원','78,700원'],['조경기능사','14,500원','30,400원','44,900원']])}<p>각각의 ${link('https://www.q-net.or.kr/crf005.do?id=crf00503s02&gSite=Q&jmInfoDivCcd=B0&jmCd=7632','산림기능사 시험정보')}와 ${link('https://www.q-net.or.kr/crf005.do?id=crf00503s02&gSite=Q&jmInfoDivCcd=B0&jmCd=7900','조경기능사 시험정보')}를 확인했습니다. 기존에 한 금액만 제시했던 부분을 두 종목으로 나누었습니다. 합계에는 교육비·보호구·도구·교통비·재응시 비용이 들어 있지 않습니다.</p><p>가령 산림 실기를 한 번 더 응시하는 상황이면 추가 접수비는 64,200원이며 조경의 30,400원을 대신 더하면 안 됩니다. 이는 재시험 발생을 가정한 산술 예이지 권장 응시 횟수나 합격비용 평균이 아닙니다.</p></section>`;
const fire=`<section class="fact-followup" data-fact-review="20261030" data-value-repair="20261030"><h2>전기 시험료와 소방 강습·시험·발급비를 구분합니다</h2>${table('서로 다른 취득 경로의 비용 항목',['대상','시험 접수비','교육비','자격 발급'],[['전기기능사','필기 14,500원 + 실기 106,200원 = 120,700원','학원·실습비 별도','신청 방식에 따른 별도 항목'],['소방안전관리자 2급','시험 1회 12,000원','본인의 응시 경로·선택 강습에 따라 별도 확인','상장형 무료 / 수첩형 10,000원']])}<p>전기 금액은 ${link('https://www.q-net.or.kr/crf005.do?id=crf00503s02&gSite=Q&jmInfoDivCcd=B0&jmCd=7780','Q-Net 전기기능사 시험정보')}, 2급 소방 시험료는 ${link('https://www.kfsi.or.kr/assets/downloadDoc/33.pdf','한국소방안전원 2급 시험 안내')}, 발급비는 ${link('https://safe.kfsi.or.kr/certificate/issueInfo.do','소방안전24 자격 발급 안내')}에서 2026년 10월 30일 확인했습니다. 2급 사례를 다른 등급에 일괄 적용하지 않습니다.</p><p>소방의 12,000원을 전체 취득비로 읽으면 안 됩니다. 강습이 필요한 경로인지 먼저 확인하고 해당 과정의 실제 결제액·이동비와 발급 형태를 따로 넣으세요. 예컨대 시험을 두 번 보고 수첩형을 선택하면 이 두 항목만 12,000×2+10,000=34,000원이며 강습비 등은 빠진 계산입니다. 자격발급과 건물 선임은 별도 절차입니다.</p></section>`;
